import{_ as t}from"./chunks/telegram.CcKrwDlC.js";import{_ as o,o as a,c as n,a2 as r}from"./chunks/framework.DSc8fo6x.js";const u=JSON.parse('{"title":"Telegram: daily report and backup","description":"","frontmatter":{},"headers":[],"relativePath":"en/telegram.md","filePath":"en/telegram.md"}'),s={name:"en/telegram.md"};function i(d,e,l,g,c,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="telegram-daily-report-and-backup" tabindex="-1">Telegram: daily report and backup <a class="header-anchor" href="#telegram-daily-report-and-backup" aria-label="Permalink to &quot;Telegram: daily report and backup&quot;">​</a></h1><p>Every evening a short <strong>report</strong> (sales, revenue, cash and card, voids — who did them, products running low) and an <strong>encrypted backup</strong> arrive on the owner&#39;s phone. Even if the computer is stolen or breaks, the copy in Telegram stays.</p><p><strong>If no message arrives, that itself is a warning:</strong> something is wrong.</p><h2 id="connecting-once-internet-needed" tabindex="-1">Connecting (once, internet needed) <a class="header-anchor" href="#connecting-once-internet-needed" aria-label="Permalink to &quot;Connecting (once, internet needed)&quot;">​</a></h2><ol><li>On your phone, find <strong>@BotFather</strong> in Telegram → <code>/newbot</code> → give the bot a name (e.g. &quot;Shop Kassa&quot;) and a username (it must end with <code>bot</code>).</li><li>BotFather gives you a long <strong>token</strong> (<code>123456789:AA…</code>). Copy it.</li><li>Kassa → <strong>Settings → Telegram</strong> → paste it into the <strong>Bot token</strong> field.</li><li>Find your bot in Telegram and send it <strong><code>/start</code></strong>. <ul><li><strong>To send to a group:</strong> add the bot to the group and send <strong><code>/start@your_bot_name</code></strong> in the group (e.g. <code>/start@magaza_kassa_bot</code>). An ordinary message is not enough — Telegram does not show ordinary group messages to bots.</li></ul></li><li>In Kassa, press <strong>Find chat</strong>. If several chats are found (private and group), choose one from the list. The choice is <strong>saved by itself</strong>.</li><li>Choose the report time (e.g. 21:00) → <strong>Test message</strong>. A message should arrive on your phone.</li></ol><p><img src="'+t+'" alt="Telegram"></p><h2 id="after-that" tabindex="-1">After that <a class="header-anchor" href="#after-that" aria-label="Permalink to &quot;After that&quot;">​</a></h2><ul><li>The report comes every day at the chosen time. If the program was closed before that time, a &quot;late report&quot; comes the next day.</li><li>Backup once a day. With a large database the file is split into parts (<code>.001</code>, <code>.002</code>…).</li><li>If there is no internet, it tries again every 15 minutes. The time and result of the last send are shown in Settings.</li><li>A saved token is not shown on the screen (the field is empty and says &quot;Saved&quot;). If someone learns the token — <code>/revoke</code> in BotFather.</li></ul><div class="warning custom-block"><p class="custom-block-title">Yellow warning &quot;Backups are not reaching Telegram&quot;</p><p>Nothing has been sent for more than 2 days. The reason is written in the warning. Check: is there internet? Was the bot deleted? Settings → Telegram → <strong>Test message</strong>.</p></div><p>How to restore a backup from Telegram: <a href="./backup.html#fayldan-berpa">Backup and restore</a>.</p>',10)])])}const f=o(s,[["render",i]]);export{u as __pageData,f as default};
